import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import makeAnimated from "react-select/animated";
import { ToastContainer, toast } from "react-toastify";
import entitiesApi from "../../../api/entitiesApi";
import countiesApi from "../../../api/countiesApi";
import restaurantApi from "../../../api/restaurants/restaurantApi";
import { Modal } from "antd";
import { Button } from "@heroui/react";

export default function BranchFormModal({
  ismodalOpen,
  setisModalOpen,
  branchToEdit,
  modalTitle = "Add new branch",
  updated,
  setUpdated,
}) {
  // const { isOpen, onOpen, onOpenChange } = useDisclosure();
  const animatedComponent = makeAnimated();
  const [branch, setBranch] = useState(branchToEdit ? branchToEdit : null);

  const [entities, setEntities] = useState([]);
  const [counties, setCounties] = useState([]);
  const [subCounties, setSubCounties] = useState([]);
  const getEntitiesActionsApi = useApi(entitiesApi.entitiesAction);

  const restaurantActionsApi = useApi(restaurantApi.restaurantAction);
  const getUserEntities = async () => {
    await getEntitiesActionsApi.request({
      action: "GetUserEntities",
    });
  };

  useEffect(() => {
    getUserEntities();
    getCounties();
  }, []);

  useEffect(() => {
    if (getEntitiesActionsApi.data && getEntitiesActionsApi.data.length) {
      setEntities(
        getEntitiesActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }

    console.log("getEntitiesActionsApi.data", getEntitiesActionsApi.data);
  }, [getEntitiesActionsApi.data]);

  const getCountiesActionsApi = useApi(countiesApi.countiesAction);
  const getCounties = async () => {
    await getCountiesActionsApi.request({
      action: "GetCounties",
    });
  };
  useEffect(() => {
    if (getCountiesActionsApi.data && getCountiesActionsApi.data.length) {
      setCounties(
        getCountiesActionsApi.data.map((i) => ({ label: i.title, value: i.id }))
      );
    }

    console.log("getCountiesActionsApi.data", getCountiesActionsApi.data);
  }, [getCountiesActionsApi.data]);

  const [errors, setErrors] = useState();

  const handleBranchAction = async (data) => {
    console.log("data at", data);
    const result = await restaurantActionsApi.request(data);

    if (result.ok) {
      console.log("res", result);
      setUpdated(true);
      setisModalOpen(false);
    } else {
      setUpdated(false);
    }
  };

  useEffect(() => {}, [branch]);

  useEffect(() => {
    if (restaurantActionsApi.data) {
      setisModalOpen(false);
      setUpdated(true);
      // if (transportActionsApi.data.destination) {
      //     setDestination(transportActionsApi.data.destination)
      // }

      if (restaurantActionsApi.data.errors) {
        setErrors(restaurantActionsApi.data.errors);
      }
    }

    console.log("transportActionsApi.data", restaurantActionsApi.data);
  }, [restaurantActionsApi.data]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const formik = useFormik({
    initialValues: {
      county: branch
        ? { label: branch.county_title, value: branch.county }
        : "",
      // sub_county: branch ? { 'label': branch.sub_county_title, 'value': branch.sub_county } : '',
      town: branch ? branch.town : "",
      road: branch ? branch.road : "",
      title: branch ? branch.title : "",
      description: branch ? branch.description : "",
      building: branch ? branch.building : "",
    },

    validationSchema: Yup.object({
      county: Yup.object().required("County is required"),
      title: Yup.string()
        .min(3, "Must be 15 characters or more")
        .required("Title is required"),
      town: Yup.string()
        .min(3, "Must be 3 characters or more")
        .required("Town is required"),
      road: Yup.string()
        .min(0, "Must be 3 characters or more")
        .required("Road is required"),
      building: Yup.string()
        .min(0, "Must be 3 characters or more")
        .required("Building is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      setErrors([]);

      if (branchToEdit) {
        handleBranchAction({
          action: "UpdateRestaurantBranch",
          branch_details: {
            branch: branch.id,
            title: values.title,
            county: values.county.id,
            town: values.town,
            road: values.road,
            building: values.building,
            description: values.description ? values.description : "",
          },
        });
      } else {
        handleBranchAction({
          action: "CreateRestaurantBranch",
          branch_details: {
            county: values.county ? values.county.value : "",
            title: values.title,
            town: values.town,
            road: values.road,
            building: values.building,
            description: values.description ? values.description : "",
          },
        });
      }

      // resetForm();
    },
  });

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  return (
    <div className="w-full">
      <Modal
        width={560}
        className="w-full text-center"
        title={branchToEdit ? `EDIT ${branchToEdit.title}` : modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />

        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full my-7"
        >
          <CustomFormItem
            touched={formik.touched.county}
            error={formik.errors.county}
          >
            <CustomSelectReactSelect
              className="text-start"
              name="county"
              id="county"
              label="Select county"
              size="large"
              onChange={(value) => formik.setFieldValue("county", value)}
              value={formik.values.county}
              placeholder="Select county"
              options={counties}
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.title}
            error={formik.errors.title}
          >
            <CustomInput
              required={true}
              id="title"
              name="title"
              onChange={formik.handleChange}
              placeholder="Enter branch title"
              size="large"
              type="text"
              value={formik.values.title}
              label="Branch title"
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.town}
            error={formik.errors.town}
          >
            <CustomInput
              required={true}
              id="town"
              name="town"
              onChange={formik.handleChange}
              placeholder="Enter town where situated"
              size="large"
              type="text"
              value={formik.values.town}
              label="Route town"
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.road}
            error={formik.errors.road}
          >
            <CustomInput
              required={true}
              id="road"
              name="road"
              onChange={formik.handleChange}
              placeholder="Enter road where situated"
              size="large"
              type="text"
              value={formik.values.road}
              label="Route road"
            />
          </CustomFormItem>

          <CustomFormItem
            touched={formik.touched.building}
            error={formik.errors.building}
          >
            <CustomInput
              required={true}
              id="building"
              name="building"
              onChange={formik.handleChange}
              placeholder="Enter building where situated"
              size="large"
              type="text"
              value={formik.values.building}
              label="Branch building"
            />
          </CustomFormItem>

          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
